// The phase-plan executor. See run_plan.hpp.
#include "run_plan.hpp"

#include <cstdlib>
#include <filesystem>
#include <fstream>

#include <unistd.h>

#include "argv.hpp"
#include "process.hpp"
#include "repo_root.hpp"
#include "shm.hpp"
#include "state.hpp"

namespace fs = std::filesystem;

namespace andes_sim {
namespace {

// Each leg's drain file, threaded forward (leg i+1 resumes from leg i's).
std::string state_path(const std::string& workdir, size_t i) {
  return workdir + "/state-" + std::to_string(i) + ".bin";
}

const EngineDescriptor* find_engine(const std::vector<EngineDescriptor>& engines,
                                    const std::string& id) {
  for (const EngineDescriptor& e : engines)
    if (e.id == id) return &e;
  return nullptr;
}

// $VSIM_PLUGIN else the in-repo default (matches the e2e harness / hsim).
std::string resolve_plugin(const std::string& override_path) {
  if (!override_path.empty()) return override_path;
  if (const char* p = std::getenv("VSIM_PLUGIN"); p && *p) return p;
  return default_plugin_path().string();
}

// `--print-qemu-config` exits in the arg parser (no simulation), so the probe is
// cheap; this is a safety cap, not a real wait.
constexpr int kQemuCfgProbeMs = 5000;

}  // namespace

std::string stage_qemu_cfg(const std::string& workdir, const RunResult& probe) {
  if (probe.spawn_failed || probe.timed_out || probe.rc != 0 || probe.out.empty())
    return "";
  const std::string path = workdir + "/qemu.cfg";
  std::ofstream f(path, std::ios::binary | std::ios::trunc);
  f.write(probe.out.data(), static_cast<std::streamsize>(probe.out.size()));
  if (!f) return "";
  return path;
}

std::string plan_step_rc_error(size_t step, const Step& s, int expect_rc,
                               int got_rc) {
  std::string m = "plan step " + std::to_string(step) + ": expected exit " +
                  std::to_string(expect_rc) + ", got " + std::to_string(got_rc);
  // A drain step (expect_rc is the handoff/drain code) that exits 0 ran the ELF
  // to completion without ever hitting its ROI boundary -- the marker/pc
  // trigger never fired. This is THE common "unmarked ELF / wrong trigger"
  // mistake; name the kind so the fix is obvious, not a bare exit code.
  if (got_rc == 0 && expect_rc == kDrainRc)
    m += " -- the " + s.role + " ran to completion without reaching its " +
         s.trigger.kind +
         " trigger boundary (the ROI never drained; check the ELF actually "
         "reaches the " +
         s.trigger.kind + ")";
  return m;
}

LegTriggerArgs leg_trigger_args(const Trigger& t, const std::string& role,
                                std::string& err) {
  err.clear();
  LegTriggerArgs out;
  if (t.kind == "marker") return out;  // markers detected by plugin/vsim, not argv

  const bool fast = role == "fast-leg";
  const bool accurate = role == "accurate-leg";
  if (!fast && !accurate) return out;  // other roles carry no trigger args

  // Required-param lookup. A missing key is a caller bug; surface it (don't
  // throw) so plan_argvs can report which step failed.
  auto param = [&](const char* key) -> const std::string* {
    auto it = t.params.find(key);
    if (it == t.params.end()) {
      err = "trigger '" + t.kind + "' missing param '" + key + "'";
      return nullptr;
    }
    return &it->second;
  };

  if (t.kind == "pc") {
    if (fast) {
      if (const std::string* p = param("enter_pc"))
        out.plugin_suffix = ",enter_pc=" + *p;
    } else if (const std::string* p = param("exit_pc")) {
      out.extra = {"--hybrid-exit-pc", *p};
    }
    return out;
  }

  // verify oracle leg (verify_oracle F4): a pure-QEMU drain at the ROI exit
  // boundary, sampling at vsim's actual halt pc (drain_pc -- the DMI halt
  // lands a few insns past the trigger, and the comparison is only valid at
  // the same architectural point). qemu-only: the oracle plan has no
  // accurate leg.
  if (t.kind == "verify-marker" || t.kind == "verify-pc") {
    if (!fast) return out;
    std::string suffix = ",exit_marker=1";
    if (t.kind == "verify-pc") {
      const std::string* p = param("exit_pc");
      if (!p) return out;
      suffix = ",exit_pc=" + *p;
    }
    if (const std::string* p = param("drain_pc"))
      out.plugin_suffix = suffix + ",drain_pc=" + *p;
    return out;
  }

  err = "unknown trigger kind '" + t.kind + "'";
  return out;
}

std::vector<std::vector<std::string>> plan_argvs(
    const Plan& plan, const std::vector<EngineDescriptor>& engines,
    const std::string& workdir, const RuntimeCtx& ctx, std::string& err) {
  std::vector<std::vector<std::string>> out;
  out.reserve(plan.steps.size());
  std::string prev_state_out;  // empty for the cold first leg

  // hw-config sync: {vlen} comes from the accurate-leg engine's descriptor.
  long vlen = 0;
  for (const Step& s : plan.steps)
    if (s.role == "accurate-leg")
      if (const EngineDescriptor* e = find_engine(engines, s.engine_id))
        if (e->vlen > 0) vlen = e->vlen;
  const std::string vlen_str = std::to_string(synced_vlen(vlen));

  for (size_t i = 0; i < plan.steps.size(); ++i) {
    const Step& step = plan.steps[i];
    const EngineDescriptor* eng = find_engine(engines, step.engine_id);
    if (!eng) {
      err = "plan step " + std::to_string(i) + ": unknown engine '" +
            step.engine_id + "'";
      return {};
    }
    const std::vector<std::string>* tmpl = eng->invoke_for(step.role);
    if (!tmpl) {
      err = "plan step " + std::to_string(i) + ": engine '" + step.engine_id +
            "' has no invoke template for role '" + step.role + "'";
      return {};
    }

    std::string trig_err;
    const LegTriggerArgs lt = leg_trigger_args(step.trigger, step.role, trig_err);
    if (!trig_err.empty()) {
      err = "plan step " + std::to_string(i) + ": " + trig_err;
      return {};
    }

    const std::string state_out = state_path(workdir, i);
    const std::map<std::string, std::string> m = {
        {"bin", eng->bin_path},
        {"elf", plan.elf},
        {"plugin", ctx.plugin_path},
        {"mmap", ctx.mmap_path},
        {"mmap_size", std::to_string(ctx.mem_size)},
        {"mmap_base", ctx.mmap_base},
        {"state_in", prev_state_out},
        {"state_out", state_out},
        {"trigger", lt.plugin_suffix},  // qemu plugin comma-suffix (empty for marker)
        {"vlen", vlen_str},
    };
    std::vector<std::string> argv = build_argv(*tmpl, m, err);
    if (!err.empty()) {
      err = "plan step " + std::to_string(i) + ": " + err;
      return {};
    }
    // The QEMU producer leg loads the accurate engine's ISA via -readconfig (its
    // config.inc distilled to per-extension globals), so QEMU1 executes the same
    // extensions the engine models. Empty => keep the descriptor's default -cpu.
    if (step.role == "fast-leg" && !ctx.qemu_cfg.empty()) {
      argv.push_back("-readconfig");
      argv.push_back(ctx.qemu_cfg);
    }
    // Trigger's vsim tokens, then user-forwarded per-leg flags -- both verbatim
    // after the filled template (matches tests/e2e.sh's ordering).
    argv.insert(argv.end(), lt.extra.begin(), lt.extra.end());
    argv.insert(argv.end(), step.extra_args.begin(), step.extra_args.end());
    out.push_back(std::move(argv));
    prev_state_out = state_out;
  }
  err.clear();
  return out;
}

PlanResult run_plan(const Plan& plan,
                    const std::vector<EngineDescriptor>& engines,
                    const PlanOptions& opts) {
  PlanResult res;
  if (plan.steps.empty()) {
    res.error = "plan has no steps";
    return res;
  }

  // Acquire the shared mmap: allocate one (and own it) when none is pinned.
  std::string mmap_path = plan.mmap_path;
  const bool own_mmap = mmap_path.empty();
  if (own_mmap) {
    std::string err;
    // L26/F2: back the mmap with one V-scratch page above the program's RAM.
    mmap_path = allocate(physical_mmap_bytes(plan.mem_size), err);
    if (mmap_path.empty()) {
      res.error = err;
      return res;
    }
  }

  // A private dir for the threaded drain files.
  std::error_code ec;
  fs::path workdir = fs::temp_directory_path(ec) / "andesim-plan-XXXXXX";
  std::string tmpl = workdir.string();
  std::vector<char> tbuf(tmpl.begin(), tmpl.end());
  tbuf.push_back('\0');
  const char* made = ::mkdtemp(tbuf.data());
  if (!made) {
    if (own_mmap) ::unlink(mmap_path.c_str());
    res.error = "failed to create plan work dir";
    return res;
  }
  const std::string wd = made;

  RuntimeCtx ctx;
  ctx.mmap_path = mmap_path;
  // L26/F2: the legs (QEMU backend size, vsim --shared-mem-size) see the
  // PHYSICAL window -- program RAM plus the V-scratch page. The program's own
  // linker script still uses only --mem-size, so the scratch page sits above
  // everything it can address.
  ctx.mem_size = physical_mmap_bytes(plan.mem_size);
  ctx.plugin_path = resolve_plugin(opts.plugin_path);  // mmap_base keeps its "0x0" default

  // Match the QEMU producer leg's ISA to the accurate engine: ask that engine
  // for a QEMU -readconfig cfg distilled from its config.inc. Tolerant -- an
  // engine without --print-qemu-config leaves qemu_cfg empty (the parser throws
  // on the unknown flag -> non-zero exit), so the fast leg keeps its -cpu.
  for (const Step& s : plan.steps)
    if (s.role == "accurate-leg")
      if (const EngineDescriptor* e = find_engine(engines, s.engine_id);
          e && !e->bin_path.empty()) {
        ctx.qemu_cfg = stage_qemu_cfg(
            wd, run_process({e->bin_path, "--print-qemu-config"}, kQemuCfgProbeMs));
        break;
      }

  std::string err;
  const std::vector<std::vector<std::string>> argvs =
      plan_argvs(plan, engines, wd, ctx, err);
  if (!err.empty()) {
    res.error = err;
  } else if (opts.dry_run) {
    // Build-only: the argvs are fully resolved (placeholders, staged qemu_cfg,
    // threaded state paths) -- record them for the caller to print, spawn none.
    res.argvs = argvs;
  } else {
    res.argvs = argvs;
    for (size_t i = 0; i < argvs.size(); ++i) {
      const RunResult r = run_process(argvs[i], opts.timeout_ms);
      if (r.spawn_failed) {
        res.error = "plan step " + std::to_string(i) + ": failed to spawn";
        break;
      }
      if (r.timed_out) {
        res.error = "plan step " + std::to_string(i) + ": timed out after " +
                    std::to_string(opts.timeout_ms) + " ms";
        break;
      }
      if (r.rc != opts.expect_rc) {
        res.error = plan_step_rc_error(i, plan.steps[i], opts.expect_rc, r.rc);
        break;
      }
      const StateFile sf = read_state_file(state_path(wd, i));
      if (!sf.ok()) {
        res.error = "plan step " + std::to_string(i) + ": " + sf.error;
        break;
      }
      res.phases.push_back({sf.st.mcycle, sf.st.minstret, r.out, sf.st});
    }
  }

  fs::remove_all(wd, ec);
  if (own_mmap) ::unlink(mmap_path.c_str());
  return res;
}

}  // namespace andes_sim

// `andesim run --mode fast|cycle|hybrid [engine selection] ELF [-- engine args]`.
//
// The top selection axis. F7 lands the first standalone model, `fast` (QEMU
// alone, functional): resolve the built-in qemu engine, then hand off to
// transparent passthrough -- the ELF plus everything after `--` becomes the
// engine's own command line, run with inherited stdio, no timeout, and the
// exit code propagated, so a gdbstub / monitor / semihosting console all
// behave as if the engine were invoked directly. `cycle` (F8) and `hybrid`
// (F9) land in later features; their dispatch arms stub for now.
#include <cstdio>
#include <filesystem>
#include <string>
#include <vector>

#include "cli.hpp"
#include "engine_descriptor.hpp"
#include "engine_registry.hpp"
#include "models.hpp"
#include "process.hpp"
#include "run_passthrough.hpp"

namespace fs = std::filesystem;

namespace andes_sim {
namespace {

// Resolve `path` to an absolute, EXISTING ELF. Returns the resolved string on
// success; on failure prints an error tagged with `ctx` and returns "". The
// existence check is here, at the shared resolver, so a missing path fails
// with a clear "ELF not found" instead of being handed to the engine (e.g.
// qemu's cryptic "Unable to find the RISC-V BIOS").
std::string abs_elf(const std::string& path, const std::string& ctx) {
  std::error_code ec;
  fs::path abs = fs::absolute(path, ec);
  if (ec) {
    std::fprintf(stderr, "andesim run %s: cannot resolve ELF '%s'\n",
                 ctx.c_str(), path.c_str());
    return "";
  }
  if (!fs::is_regular_file(abs, ec)) {
    std::fprintf(stderr, "andesim run %s: ELF not found: %s\n", ctx.c_str(),
                 path.c_str());
    return "";
  }
  return abs.string();
}

// Validate the lone-ELF positional shape the standalone models require: print
// the diagnostic and return 2 on a violation, else 0. `model` labels the error.
int check_one_elf(const Cli& cli, const char* model) {
  if (cli.positional.empty()) {
    std::fprintf(stderr,
                 "andesim run --mode %s: missing ELF (the workload to run; "
                 "e.g. a tests/fixtures/<name>.elf)\n",
                 model);
    return 2;
  }
  if (cli.positional.size() > 1) {
    std::fprintf(stderr,
                 "andesim run --mode %s: unexpected argument '%s' "
                 "(engine args go after --)\n",
                 model, cli.positional[1].c_str());
    return 2;
  }
  return 0;
}

// The standalone spine: take a single ELF, then run the resolved engine
// standalone with the post-`--` args appended verbatim (exec_passthrough --
// inherit stdio, no timeout, propagate the exit code, so an interactive
// gdbstub / monitor / semihosting console works unchanged). The per-model
// engine + selection are resolved by the caller; `model` here only labels
// the positional diagnostics.
int run_standalone(const Cli& cli, const EngineDescriptor& eng,
                   const char* model) {
  if (int rc = check_one_elf(cli, model)) return rc;
  // QEMU's -bios flag searches its data directory for relative paths rather
  // than the CWD; resolve to absolute so the engine finds the ELF.
  const std::string elf = abs_elf(cli.positional[0], "--mode " + std::string(model));
  if (elf.empty()) return 2;
  std::string err;
  const std::vector<std::string> argv =
      passthrough_argv(eng, "standalone", elf, cli.passthrough, err);
  if (!err.empty()) {
    std::fprintf(stderr, "andesim run: %s\n", err.c_str());
    return 2;
  }
  return exec_passthrough(argv);
}

// `run --mode fast`: QEMU alone, functional, transparent passthrough. Needs
// only the built-in qemu descriptor, so it resolves that directly rather than
// discover_engines(), which would spawn a --describe subprocess per Verilator
// build only to discard them all here.
int run_fast(const Cli& cli) {
  // fast is QEMU-only; an explicit engine must name it.
  if (!cli.engine.empty() && cli.engine != kQemuId) {
    std::fprintf(stderr,
                 "andesim run --mode fast: engine must be 'qemu', got '%s'\n",
                 cli.engine.c_str());
    return 2;
  }
  return run_standalone(cli, builtin_qemu(), "fast");
}

}  // namespace

int cmd_run(const Cli& cli) {
  if (cli.model.empty()) {
    std::fprintf(stderr,
                 "andesim run: --mode fast|cycle|hybrid is required "
                 "(pick the composition; see 'andesim run --help')\n");
    return 2;
  }
  if (!find_model(cli.model)) {
    std::fprintf(stderr,
                 "andesim run: unknown model '%s' (want fast|cycle|hybrid)\n",
                 cli.model.c_str());
    return 2;
  }
  if (cli.model == "fast") return run_fast(cli);

  std::fprintf(stderr, "andesim run --mode %s: not yet implemented\n",
               cli.model.c_str());
  return 3;
}

}  // namespace andes_sim

// Runtime engine discovery -- the hot-plug seam.
//
// discover_engines() returns the built-in qemu descriptor plus every engine
// found by scanning a directory and asking each binary to self-report via
// `--describe` (falling back to a <bin>.json sidecar). No engine is compiled
// into the framework; dropping a freshly built sim_<cfg> into the scan dir
// makes it appear here with no andesim rebuild.
//
// Scan dir: $ANDESIM_ENGINES_DIR (colon-separated; REPLACES the default and
// accepts any executable) if set, else vsim_scan_dir() (filtered to sim_*
// binaries) -- $VSIM_BIN_DIR, the external prebuilt vsim build dir mirroring
// $QEMU_BIN_DIR, falling back to the legacy in-tree <repo>/verilator/build.
#ifndef ANDESIM_ENGINE_REGISTRY_HPP
#define ANDESIM_ENGINE_REGISTRY_HPP

#include <filesystem>
#include <string>
#include <vector>

#include "engine_descriptor.hpp"
#include "strutil.hpp"

namespace andes_sim {

// Built-in functional engine id. Declared once here so builtin_qemu and every
// lookup agree -- a renamed literal would otherwise break find_engine()
// lookups only at run time.
inline constexpr const char* kQemuId = "qemu";

struct Discovery {
  std::vector<EngineDescriptor> engines;   // deduped by id; qemu first
  std::vector<std::string> warnings;       // binaries that failed to describe
};

Discovery discover_engines();

// Directory discover_engines() scans for sim_* engines when $ANDESIM_ENGINES_DIR
// is unset: VSIM_BIN_DIR (the external prebuilt vsim build, mirroring
// QEMU_BIN_DIR) resolved env-first then from config.env, else the legacy in-tree
// <repo>/verilator/build.
std::filesystem::path vsim_scan_dir();

// The bundled qemu descriptor (no directory scan, no --describe subprocess).
// discover_engines() seeds the registry with it; `run --mode fast` resolves
// qemu through it directly, paying none of the Verilator-engine discovery cost.
EngineDescriptor builtin_qemu();

// Rewrite a discovered engine's identity from the third-party simulator name to
// the product name: type "verilator" -> "vsim", id "verilator:<cfg>" ->
// "vsim:<cfg>". discover_engines() applies this once, before the id is used for
// dedup or shown anywhere, so every downstream consumer (list / --engine /
// errors / run banner) speaks "vsim" and a user never sees "verilator". Any
// other backend (qemu, a drop-in alioth/sid) passes through untouched.
inline void normalize_engine_label(EngineDescriptor& d) {
  if (d.type == "verilator") d.type = "vsim";
  if (d.id.rfind("verilator:", 0) == 0) d.id = "vsim:" + d.id.substr(10);
  // The CLI exposes the marker delimiter as `--trigger marker`; some engines
  // report it under their internal name "csr" via --describe. Speak the CLI's
  // vocabulary in list too, like verilator -> vsim above.
  for (std::string& t : d.triggers)
    if (t == "csr") t = "marker";
}

}  // namespace andes_sim

#endif  // ANDESIM_ENGINE_REGISTRY_HPP
// EngineDescriptor: the parsed result of an engine's `--describe` (or its
// sidecar <bin>.json). This struct IS the contract that QEMU, Verilator, and
// future engines (alioth, sid) speak to join the framework -- see
// docs/engine_interface.md. The framework keeps zero per-engine code; every
// capability it needs comes from here.
#ifndef ANDESIM_ENGINE_DESCRIPTOR_HPP
#define ANDESIM_ENGINE_DESCRIPTOR_HPP

#include <string>
#include <string_view>
#include <vector>

#include "json.hpp"

namespace andes_sim {

// One role's argv template, e.g. role "accurate-leg" -> {"{bin}",
// "--resume-from-qemu", "{state_in}", ...}. {placeholders} are filled by the
// plan executor (F6).
struct EngineInvoke {
  std::string role;
  std::vector<std::string> argv;
};

struct EngineDescriptor {
  std::string id;                       // "qemu", "verilator:ax45mpv_premium"
  std::string type;                     // qemu | verilator | alioth | sid
  std::string kind;                     // functional | cycle-accurate
  long vlen = 0;                        // 0 = not reported
  long xlen = 0;
  std::vector<std::string> triggers;    // marker | pc
  std::vector<std::string> roles;       // standalone | fast-leg | accurate-leg
  std::vector<std::string> state;       // resume | drain (hybrid_state_v1 caps)
  std::vector<EngineInvoke> invoke;     // argv template per role
  std::string result;                   // stderr:<re> | state.mcycle

  // Filled by the registry, not present in the JSON:
  std::string bin_path;                 // resolved path to the binary
  std::string source;                   // built-in | --describe | sidecar

  const std::vector<std::string>* invoke_for(std::string_view role) const {
    for (const EngineInvoke& iv : invoke)
      if (iv.role == role) return &iv.argv;
    return nullptr;
  }
};

// Build a descriptor from parsed JSON. Returns "" on success or an error
// message naming the first problem (id and type are required).
inline std::string descriptor_from_json(const json::Value& v,
                                        EngineDescriptor& out) {
  if (!v.is_object()) return "descriptor is not a JSON object";

  const json::Value* id = v.find("id");
  if (!id || !id->is_string() || id->str.empty()) return "missing string 'id'";
  out.id = id->as_string();

  const json::Value* type = v.find("type");
  if (!type || !type->is_string()) return "missing string 'type'";
  out.type = type->as_string();

  if (const json::Value* x = v.find("kind")) out.kind = x->as_string();
  if (const json::Value* x = v.find("vlen")) out.vlen = x->as_int();
  if (const json::Value* x = v.find("xlen")) out.xlen = x->as_int();
  if (const json::Value* x = v.find("triggers")) out.triggers = x->as_string_array();
  if (const json::Value* x = v.find("roles")) out.roles = x->as_string_array();
  if (const json::Value* x = v.find("state")) out.state = x->as_string_array();
  if (const json::Value* x = v.find("result")) out.result = x->as_string();

  if (const json::Value* inv = v.find("invoke"); inv && inv->is_object()) {
    for (size_t k = 0; k < inv->keys.size(); ++k)
      out.invoke.push_back({inv->keys[k], inv->vals[k].as_string_array()});
  }
  return "";
}

}  // namespace andes_sim

#endif  // ANDESIM_ENGINE_DESCRIPTOR_HPP

