// argv assembly for `run --mode fast`.
//
// The framework parses only its selection flags; everything after `--` is the
// engine's own CLI. passthrough_argv fills the engine's role invoke template
// ({bin}/{elf}) and appends those verbatim args. cmd_run then runs the result
// transparently (exec_passthrough -- inherited stdio, an interactive gdbstub /
// monitor / console unchanged).
#ifndef ANDESIM_RUN_PASSTHROUGH_HPP
#define ANDESIM_RUN_PASSTHROUGH_HPP

#include <string>
#include <vector>

#include "engine_descriptor.hpp"

namespace andes_sim {

// Assemble the argv: fill `eng`'s `role` invoke template ({bin}/{elf}) then
// append `passthrough` verbatim. On an unknown role or unknown placeholder,
// sets `err` and returns {}. `elf` is substituted as-is; validating that a
// positional was actually given is the caller's job.
std::vector<std::string> passthrough_argv(
    const EngineDescriptor& eng, const std::string& role, const std::string& elf,
    const std::vector<std::string>& passthrough, std::string& err);

}  // namespace andes_sim

#endif  // ANDESIM_RUN_PASSTHROUGH_HPP
// argv assembly for run --mode fast. See run_passthrough.hpp.
#include "run_passthrough.hpp"

#include "argv.hpp"

namespace andes_sim {

std::vector<std::string> passthrough_argv(
    const EngineDescriptor& eng, const std::string& role, const std::string& elf,
    const std::vector<std::string>& passthrough, std::string& err) {
  const std::vector<std::string>* tmpl = eng.invoke_for(role);
  if (!tmpl) {
    err = "engine '" + eng.id + "' has no invoke template for role '" + role +
          "'";
    return {};
  }
  std::vector<std::string> argv =
      build_argv(*tmpl, {{"bin", eng.bin_path}, {"elf", elf}}, err);
  if (!err.empty()) return {};
  argv.insert(argv.end(), passthrough.begin(), passthrough.end());
  return argv;
}

}  // namespace andes_sim
// Subprocess helpers for andesim.
//
// run_process spawns a child, captures its stdout, and kills it after a
// timeout -- the primitive the engine registry uses to ask `<bin> --describe`
// and the plan executor (F6) uses to run orchestrated legs. F5 extends this
// file with exec_passthrough (inherit stdio, no timeout) for fast/cycle.
#ifndef ANDESIM_PROCESS_HPP
#define ANDESIM_PROCESS_HPP

#include <string>
#include <vector>

namespace andes_sim {

struct RunResult {
  int rc = -1;                // child exit status, or -1 if killed/abnormal
  std::string out;            // captured stdout
  bool timed_out = false;     // killed because it exceeded the timeout
  bool spawn_failed = false;  // pipe/fork failed before the child ran
};

// Run argv (argv[0] resolved via PATH), capturing stdout. The child's stdin
// and stderr are redirected to /dev/null. If the child runs longer than
// timeout_ms it is SIGKILLed and timed_out is set.
RunResult run_process(const std::vector<std::string>& argv, int timeout_ms);

// Run argv to completion with the child INHERITING all three std streams
// (stdin, stdout, stderr) -- the transparent-passthrough mechanism behind
// `run --mode fast`: the engine reads/writes the terminal directly, so an
// interactive gdbstub or semihosting console works unchanged. No chdir,
// no capture, no timeout. Returns the child's exit code, 128+signal if it was
// signalled, or -1 on spawn failure / empty argv.
int exec_passthrough(const std::vector<std::string>& argv);

}  // namespace andes_sim

#endif  // ANDESIM_PROCESS_HPP

