// Unit tests for the F6 phase-plan executor's pure core:
//   - build_argv  (driver/argv.hpp)     invoke-template placeholder fill
//   - plan_argvs  (driver/run_plan.hpp) state-file threading across steps
//
// These cover everything in run_plan EXCEPT the live spawn loop, which the
// integration acceptance (tests/andes_sim/test_andes_sim_f6.sh -> a real
// 2-step qemu+vsim run) exercises. Plain assert-and-count harness; run by that
// same f6 script. No QEMU2 leg exists -- handback was removed.
#include <filesystem>
#include <fstream>
#include <iterator>
#include <map>
#include <string>
#include <vector>

#include "argv.hpp"
#include "engine_descriptor.hpp"
#include "plan.hpp"
#include "process.hpp"
#include "run_plan.hpp"
#include "test_check.hpp"

using namespace andes_sim;
using andes_sim::test::check_eq;

namespace {

// The canonical drain templates (what builtin_qemu() and vsim --describe ship).
const std::vector<std::string> kQemuFastLeg = {
    "{bin}",
    "-object", "memory-backend-file,id=mem,share=on,mem-path={mmap},size={mmap_size}",
    "-machine", "andes_ae350,memory-backend=mem",
    "-cpu", "andes-ax45mpv,vlen={vlen}",
    "-nographic",
    "-semihosting-config", "enable=on,target=native",
    "-bios", "{elf}",
    "-plugin", "{plugin},outfile={state_out}{trigger}",
};

const std::vector<std::string> kVsimAccurateLeg = {
    "{bin}", "{elf}",
    "--resume-from-qemu", "{state_in}",
    "--handoff-out", "{state_out}",
    "--shared-mem-path", "{mmap}",
    "--shared-mem-size", "{mmap_size}",
    "--shared-mem-base", "{mmap_base}",
};

EngineDescriptor fake(const std::string& id, const std::string& bin,
                      const std::string& role,
                      const std::vector<std::string>& tmpl) {
  EngineDescriptor d;
  d.id = id;
  d.bin_path = bin;
  d.invoke.push_back({role, tmpl});
  return d;
}

}  // namespace

int main() {
  // --- build_argv: every placeholder filled, including substring + repeat ---
  {
    std::string err;
    std::map<std::string, std::string> ctx = {
        {"bin", "/q"},      {"elf", "/e"},     {"plugin", "/p"},
        {"mmap", "/m"},     {"mmap_size", "134217728"}, {"state_out", "/s0"},
        {"trigger", ""},  // marker: no plugin suffix
        {"vlen", "512"},
    };
    std::vector<std::string> got = build_argv(kQemuFastLeg, ctx, err);
    CHECK(err.empty());
    check_eq(got,
             {"/q", "-object",
              "memory-backend-file,id=mem,share=on,mem-path=/m,size=134217728",
              "-machine", "andes_ae350,memory-backend=mem", "-cpu",
              "andes-ax45mpv,vlen=512", "-nographic", "-semihosting-config",
              "enable=on,target=native", "-bios", "/e", "-plugin",
              "/p,outfile=/s0"},
             "qemu");
  }
  {
    std::string err;
    std::map<std::string, std::string> ctx = {
        {"bin", "/v"},  {"elf", "/e"},  {"state_in", "/s0"},
        {"state_out", "/s1"}, {"mmap", "/m"}, {"mmap_size", "134217728"},
        {"mmap_base", "0x0"},
    };
    std::vector<std::string> got = build_argv(kVsimAccurateLeg, ctx, err);
    CHECK(err.empty());
    check_eq(got,
             {"/v", "/e", "--resume-from-qemu", "/s0", "--handoff-out", "/s1",
              "--shared-mem-path", "/m", "--shared-mem-size", "134217728",
              "--shared-mem-base", "0x0"},
             "vsim");
  }
  // a repeated placeholder expands every occurrence
  {
    std::string err;
    std::vector<std::string> got =
        build_argv({"a={x},b={y},a2={x}"}, {{"x", "1"}, {"y", "2"}}, err);
    CHECK(err.empty());
    check_eq(got, {"a=1,b=2,a2=1"}, "repeat");
  }
  // an unknown placeholder is an error, not a silent empty fill
  {
    std::string err;
    std::vector<std::string> got = build_argv({"{bogus}"}, {{"x", "1"}}, err);
    CHECK(got.empty());
    CHECK(!err.empty());
  }

  // --- plan_argvs: thread state files across a 2-step hybrid plan ---
  std::vector<EngineDescriptor> engines = {
      fake("qemu", "/qbin", "fast-leg", kQemuFastLeg),
      fake("vsim:test", "/vbin", "accurate-leg", kVsimAccurateLeg),
  };
  Plan plan;
  plan.elf = "/e";
  plan.mem_size = 134217728;
  plan.steps = {
      {"qemu", "fast-leg", {"marker", {}}},
      {"vsim:test", "accurate-leg", {"marker", {}}},
  };
  RuntimeCtx rc;
  rc.mmap_path = "/mm";
  rc.mem_size = 134217728;
  rc.mmap_base = "0x0";
  rc.plugin_path = "/pl";

  {
    std::string err;
    std::vector<std::vector<std::string>> argvs =
        plan_argvs(plan, engines, "/wd", rc, err);
    CHECK(err.empty());
    CHECK(argvs.size() == 2);
    if (argvs.size() == 2) {
      // step 0 (qemu): drains to state-0.bin; no state_in referenced
      check_eq(argvs[0],
               {"/qbin", "-object",
                "memory-backend-file,id=mem,share=on,mem-path=/mm,size=134217728",
                "-machine", "andes_ae350,memory-backend=mem", "-cpu",
                "andes-ax45mpv,vlen=512", "-nographic", "-semihosting-config",
                "enable=on,target=native", "-bios", "/e", "-plugin",
                "/pl,outfile=/wd/state-0.bin"},
               "step0");
      // step 1 (vsim): resumes from step 0's drain, drains to state-1.bin
      check_eq(argvs[1],
               {"/vbin", "/e", "--resume-from-qemu", "/wd/state-0.bin",
                "--handoff-out", "/wd/state-1.bin", "--shared-mem-path", "/mm",
                "--shared-mem-size", "134217728", "--shared-mem-base", "0x0"},
               "step1");
    }
  }
  // --- plan_argvs: the fast leg inherits the accurate-leg engine's vlen ---
  // (hw-config sync: the engine descriptor's vlen fills {vlen} in the QEMU
  // -cpu template; an engine that reports none falls back to 512 -- covered
  // by the default plan above, whose vsim:test has no vlen.)
  {
    std::vector<EngineDescriptor> engines128 = engines;
    engines128[1].vlen = 128;  // e.g. vsim:ax66_makatau
    std::string err;
    std::vector<std::vector<std::string>> argvs =
        plan_argvs(plan, engines128, "/wd", rc, err);
    CHECK(err.empty());
    CHECK(argvs.size() == 2);
    if (argvs.size() == 2) {
      bool found = false;
      for (const std::string& a : argvs[0])
        if (a == "andes-ax45mpv,vlen=128") found = true;
      CHECK(found);
    }
  }

  // --- render_argv: a shell-quoted, copy-pasteable command line ---
  // Safe tokens (qemu's comma/equals args, paths) pass through untouched;
  // empty, spaces, and quotes get POSIX single-quoting so the line is runnable.
  {
    CHECK(render_argv({"qemu", "-cpu", "andes-ax45mpv,vlen=512"}) ==
          "qemu -cpu andes-ax45mpv,vlen=512");
    CHECK(render_argv({"-object",
                       "memory-backend-file,id=mem,mem-path=/m,size=134217728"}) ==
          "-object memory-backend-file,id=mem,mem-path=/m,size=134217728");
    CHECK(render_argv({"-readconfig", "/tmp/a b/qemu.cfg"}) ==
          "-readconfig '/tmp/a b/qemu.cfg'");
    CHECK(render_argv({"x", ""}) == "x ''");
    CHECK(render_argv({"it's"}) == "'it'\\''s'");
  }

  // --- stage_qemu_cfg: a clean probe writes the cfg; a failed probe falls back ---
  // The accurate engine's `--print-qemu-config` stdout becomes workdir/qemu.cfg;
  // any probe failure (engine lacks the flag -> non-zero exit, timeout, empty)
  // yields "" so the fast leg keeps its default -cpu.
  {
    namespace fs = std::filesystem;
    const fs::path dir = fs::temp_directory_path() / "andesim-fa2-stage";
    fs::remove_all(dir);
    fs::create_directories(dir);

    RunResult ok;
    ok.rc = 0;
    ok.out = "[global]\ndriver = \"andes-ax45mpv-riscv-cpu\"\nproperty = \"v\"\n";
    const std::string p = stage_qemu_cfg(dir.string(), ok);
    CHECK(p == (dir / "qemu.cfg").string());
    {
      std::ifstream f(p);
      const std::string c((std::istreambuf_iterator<char>(f)),
                          std::istreambuf_iterator<char>());
      CHECK(c == ok.out);
    }

    RunResult unknown_flag;  // engine without --print-qemu-config: parser throws
    unknown_flag.rc = 1;
    unknown_flag.out = "Unrecognized option: --print-qemu-config\n";
    CHECK(stage_qemu_cfg(dir.string(), unknown_flag).empty());

    RunResult timed_out;
    timed_out.timed_out = true;
    CHECK(stage_qemu_cfg(dir.string(), timed_out).empty());

    RunResult empty_out;  // exit 0 but nothing emitted -> nothing to load
    empty_out.rc = 0;
    CHECK(stage_qemu_cfg(dir.string(), empty_out).empty());

    fs::remove_all(dir);
  }

  // --- plan_argvs: a QEMU readconfig cfg is injected into the fast leg only ---
  // The engine's config.inc, distilled to a QEMU `-readconfig` cfg, makes the
  // QEMU producer match the accurate engine's ISA. Only the fast (QEMU) leg
  // gets `-readconfig <cfg>`; the vsim accurate leg never does. An empty cfg
  // injects nothing (fallback to the descriptor's default -cpu).
  {
    RuntimeCtx rcfg = rc;
    rcfg.qemu_cfg = "/wd/qemu.cfg";
    std::string err;
    std::vector<std::vector<std::string>> argvs =
        plan_argvs(plan, engines, "/wd", rcfg, err);
    CHECK(err.empty());
    CHECK(argvs.size() == 2);
    if (argvs.size() == 2) {
      bool fast_has = false;
      for (size_t k = 0; k + 1 < argvs[0].size(); ++k)
        if (argvs[0][k] == "-readconfig" && argvs[0][k + 1] == "/wd/qemu.cfg")
          fast_has = true;
      CHECK(fast_has);
      for (const std::string& a : argvs[1]) CHECK(a != "-readconfig");
    }
  }
  // empty qemu_cfg (the default rc) injects no -readconfig on either leg
  {
    std::string err;
    std::vector<std::vector<std::string>> argvs =
        plan_argvs(plan, engines, "/wd", rc, err);
    CHECK(err.empty());
    if (argvs.size() == 2)
      for (const std::vector<std::string>& a : argvs)
        for (const std::string& tok : a) CHECK(tok != "-readconfig");
  }

  // --- leg_trigger_args: a trigger's per-role argv contribution ---
  {
    std::string err;
    // marker drives nothing into the argv; the plugin/vsim detect markers.
    LegTriggerArgs marker = leg_trigger_args({"marker", {}}, "fast-leg", err);
    CHECK(err.empty());
    CHECK(marker.plugin_suffix.empty());
    CHECK(marker.extra.empty());

    // pc: qemu gets the enter_pc plugin suffix; vsim gets the exit-pc tokens.
    const Trigger pc = {"pc", {{"enter_pc", "0x10"}, {"exit_pc", "0x20"}}};
    LegTriggerArgs pf = leg_trigger_args(pc, "fast-leg", err);
    CHECK(err.empty());
    CHECK(pf.plugin_suffix == ",enter_pc=0x10");
    CHECK(pf.extra.empty());
    LegTriggerArgs pa = leg_trigger_args(pc, "accurate-leg", err);
    CHECK(err.empty());
    CHECK(pa.plugin_suffix.empty());
    check_eq(pa.extra, {"--hybrid-exit-pc", "0x20"}, "pc-acc");

    // a role outside fast-leg/accurate-leg carries no trigger args
    LegTriggerArgs none = leg_trigger_args(pc, "standalone", err);
    CHECK(err.empty());
    CHECK(none.plugin_suffix.empty());
    CHECK(none.extra.empty());

    // unknown trigger kind / missing required param are errors
    leg_trigger_args({"bogus", {}}, "fast-leg", err);
    CHECK(!err.empty());
    leg_trigger_args({"pc", {}}, "fast-leg", err);
    CHECK(!err.empty());

    // verify oracle leg (verify_oracle F4): qemu drains at the ROI exit,
    // sampling at vsim's drained pc (drain_pc).
    const Trigger vm = {"verify-marker", {{"drain_pc", "0x100072"}}};
    LegTriggerArgs vmf = leg_trigger_args(vm, "fast-leg", err);
    CHECK(err.empty());
    CHECK(vmf.plugin_suffix == ",exit_marker=1,drain_pc=0x100072");
    CHECK(vmf.extra.empty());
    const Trigger vp = {"verify-pc",
                        {{"exit_pc", "0x20"}, {"drain_pc", "0x28"}}};
    LegTriggerArgs vpf = leg_trigger_args(vp, "fast-leg", err);
    CHECK(err.empty());
    CHECK(vpf.plugin_suffix == ",exit_pc=0x20,drain_pc=0x28");
    leg_trigger_args({"verify-marker", {}}, "fast-leg", err);
    CHECK(!err.empty());  // missing drain_pc
    leg_trigger_args({"verify-pc", {{"drain_pc", "0x28"}}}, "fast-leg", err);
    CHECK(!err.empty());  // missing exit_pc
  }

  // --- plan_argvs: pc trigger threads enter_pc (qemu) + exit_pc (vsim) ---
  {
    Plan p = plan;
    const Trigger pc = {"pc", {{"enter_pc", "0x100000"}, {"exit_pc", "0x100042"}}};
    p.steps[0].trigger = pc;
    p.steps[1].trigger = pc;
    std::string err;
    std::vector<std::vector<std::string>> argvs =
        plan_argvs(p, engines, "/wd", rc, err);
    CHECK(err.empty());
    CHECK(argvs.size() == 2);
    if (argvs.size() == 2) {
      // qemu: enter_pc folded into the single -plugin token (its last arg)
      CHECK(argvs[0].back() == "/pl,outfile=/wd/state-0.bin,enter_pc=0x100000");
      // vsim: --hybrid-exit-pc appended verbatim after the filled template
      check_eq(argvs[1],
               {"/vbin", "/e", "--resume-from-qemu", "/wd/state-0.bin",
                "--handoff-out", "/wd/state-1.bin", "--shared-mem-path", "/mm",
                "--shared-mem-size", "134217728", "--shared-mem-base", "0x0",
                "--hybrid-exit-pc", "0x100042"},
               "pc-step1");
    }
  }

  // --- plan_argvs: Step.extra_args append AFTER trigger args (e2e.sh order) ---
  {
    Plan p = plan;
    const Trigger pc = {"pc", {{"enter_pc", "0x100000"}, {"exit_pc", "0x100042"}}};
    p.steps[0].trigger = pc;
    p.steps[1].trigger = pc;
    p.steps[1].extra_args = {"--kanata", "k.txt"};
    std::string err;
    std::vector<std::vector<std::string>> argvs =
        plan_argvs(p, engines, "/wd", rc, err);
    CHECK(err.empty());
    if (argvs.size() == 2) {
      const std::vector<std::string>& v = argvs[1];
      CHECK(v.size() >= 4);
      // tail order: ... --hybrid-exit-pc 0x100042 --kanata k.txt
      CHECK(v[v.size() - 4] == "--hybrid-exit-pc");
      CHECK(v[v.size() - 3] == "0x100042");
      CHECK(v[v.size() - 2] == "--kanata");
      CHECK(v.back() == "k.txt");
    }
  }

  // unknown engine id is an error
  {
    Plan bad = plan;
    bad.steps[0].engine_id = "nope";
    std::string err;
    CHECK(plan_argvs(bad, engines, "/wd", rc, err).empty());
    CHECK(!err.empty());
  }
  // a role the engine has no template for is an error
  {
    Plan bad = plan;
    bad.steps[1].role = "no-such-role";
    std::string err;
    CHECK(plan_argvs(bad, engines, "/wd", rc, err).empty());
    CHECK(!err.empty());
  }

  // plan_step_rc_error: a drain leg that exits 0 ran the workload to completion
  // without ever reaching its ROI boundary -- the trigger never fired. The
  // message must say so and name the trigger kind, not just the bare
  // "expected exit 200, got 0" the user cannot act on.
  {
    const Step s{"qemu", "fast-leg", {"marker", {}}};
    const std::string m = plan_step_rc_error(0, s, 200, 0);
    CHECK(m.find("plan step 0") != std::string::npos);
    CHECK(m.find("marker") != std::string::npos);
    CHECK(m.find("without reaching") != std::string::npos);
  }
  // a genuine non-zero failure (engine crash, not a clean completion) keeps the
  // bare line -- no false "trigger never fired" claim.
  {
    const Step s{"qemu", "fast-leg", {"marker", {}}};
    const std::string m = plan_step_rc_error(1, s, 200, 139);
    CHECK(m.find("expected exit 200, got 139") != std::string::npos);
    CHECK(m.find("without reaching") == std::string::npos);
  }

  return andes_sim::test::report("plan");
}

// F6 integration acceptance: a real 2-step hybrid plan, end to end.
//
// Unlike plan_test.cpp (pure, fake descriptors), this discovers the real
// engines, builds a marker-trigger [qemu fast-leg -> verilator accurate-leg] plan
// on a fixture ELF, and runs it through run_plan -- spawning actual QEMU + vsim
// and threading the drained hybrid_state_v1 between them. It asserts the
// done-when: the plan succeeds and the vsim leg's mcycle exceeds the qemu leg's
// (vsim restores qemu's mcycle then counts real cycles, so the delta is the
// measured kernel's cycle count). There is no QEMU2 leg -- handback was removed.
//
// Requires built artifacts (qemu, vsim, plugin, the fixture). Run by
// tests/andes_sim/test_andes_sim_f6.sh. ELF overridable via argv[1].
#include <cstdio>
#include <string>
#include <vector>

#include "engine_registry.hpp"
#include "plan.hpp"
#include "repo_root.hpp"
#include "run_plan.hpp"
#include "test_check.hpp"

using namespace andes_sim;

int main(int argc, char** argv) {
  const std::string elf =
      argc > 1 ? std::string(argv[1])
               : (repo_root() / "tests" / "fixtures" / "handoff_roundtrip.elf")
                     .string();

  const Discovery disc = discover_engines();

  // Pick the first cycle-accurate engine that can play the accurate leg.
  const EngineDescriptor* vsim = nullptr;
  for (const EngineDescriptor& e : disc.engines)
    if (e.type == "vsim" && e.invoke_for("accurate-leg")) {
      vsim = &e;
      break;
    }
  CHECK(vsim != nullptr);
  if (!vsim) return andes_sim::test::report("plan-itest");

  std::printf("[f6-itest] elf=%s engine=%s\n", elf.c_str(), vsim->id.c_str());

  Plan plan;
  plan.elf = elf;
  plan.mem_size = 128LL * 1024 * 1024;  // program RAM; run_plan adds the
                                        // L26/F2 V-scratch page for the mmap
  plan.steps = {
      {"qemu64", "fast-leg", {"marker", {}}},
      {vsim->id, "accurate-leg", {"marker", {}}},
  };

  const PlanResult r = run_plan(plan, disc.engines);
  if (!r.ok())
    std::fprintf(stderr, "[f6-itest] run_plan error: %s\n", r.error.c_str());
  CHECK(r.ok());
  CHECK(r.phases.size() == 2);

  if (r.phases.size() == 2) {
    const unsigned long long q = r.phases[0].mcycle;
    const unsigned long long v = r.phases[1].mcycle;
    std::printf(
        "[f6-itest] qemu1 mcycle=%llu  vsim mcycle=%llu  kernel_cycles=%llu\n",
        q, v, v - q);
    CHECK(v > q);  // vsim measured a non-empty ROI
    CHECK(r.phases[1].minstret >= r.phases[0].minstret);
    CHECK(!r.phases[1].out.empty());  // leg stdout surfaced (vsim banner at minimum)
  }

  return andes_sim::test::report("plan-itest");
}
#!/usr/bin/env bash
# F8 contract: `run --mode cycle` -- one cycle-accurate engine alone, from
# reset (no QEMU, no --resume-from-qemu), transparent passthrough. Layers:
#
#   1. run-test (unit, fast): resolve_accurate_engine's selection branches
#      (default-sole / explicit / ambiguous / missing / wrong-kind) + the F7
#      passthrough_argv assembly. Pure, no spawn.
#   2. fake-engine resolution + exec (no real vsim): a handful of throwaway
#      "engine" scripts that answer `--describe` with JSON and echo a marker
#      when run. Drives the real discover -> resolve -> run_standalone -> exec
#      path end to end. Proves the done-when "selecting a different built <cfg>
#      runs the other binary" deterministically, plus every error path. The
#      fakes ship the SAME standalone template real vsim does ({bin} {elf}), so
#      this exercises the exact argv path.
#   3. real vsim (guarded, best-effort): if a sim_<cfg> is built, invoke it
#      from reset and look for its native "N cycles simulated" line. Standalone
#      from-reset of a hybrid-oriented fixture is environment-dependent, so a
#      timeout or a missing cycle line is a skip, not a failure -- layer 2 is
#      the deterministic proof.
set -uo pipefail

SCRIPT_DIR=$(cd -- "$(dirname -- "${BASH_SOURCE[0]}")" && pwd)
ROOT=$(cd -- "$SCRIPT_DIR/../.." && pwd)
. "$SCRIPT_DIR/../lib/log.sh"

BIN="$ROOT/build/andesim"
RUNTEST="$ROOT/build/driver/andesim-run-test"

bash "$ROOT/scripts/build_driver.sh" >/dev/null 2>&1 || fail "build_driver.sh failed"

# 1. unit: resolution branches + passthrough argv
[ -x "$RUNTEST" ] || fail "missing unit-test binary: $RUNTEST"
"$RUNTEST" || fail "run unit tests (resolve_accurate_engine, passthrough_argv) failed"

# --- fixtures: throwaway engine scripts in a scanned dir --------------------
TMP=$(mktemp -d)
trap 'rm -rf "$TMP"' EXIT

# mkengine DIR FILE ID KIND MARKER: a fake engine that self-describes as KIND
# and, when run standalone, echoes RAN:MARKER so we can see which binary ran.
mkengine() {
  local f="$1/$2"
  cat >"$f" <<EOF
#!/bin/sh
if [ "\$1" = "--describe" ]; then
  printf '%s\n' '{"id":"$3","type":"vsim","kind":"$4","roles":["standalone","accurate-leg"],"invoke":{"standalone":["{bin}","{elf}"]}}'
else
  echo "RAN:$5 args:\$*"
fi
EOF
  chmod +x "$f"
}

D1="$TMP/one"; D2="$TMP/two"; DF="$TMP/func"; DE="$TMP/empty"
mkdir -p "$D1" "$D2" "$DF" "$DE"
mkengine "$D1" v1 "vsim:v1" cycle-accurate m1
mkengine "$D2" v1 "vsim:v1" cycle-accurate m1
mkengine "$D2" v2 "vsim:v2" cycle-accurate m2
mkengine "$DF" f0 "vsim:f0" functional    fm

# The "expect a real run" cases (2a/2c) reach abs_elf, which requires an
# EXISTING file (a typo'd path fails with "ELF not found" before the engine
# spawns); contents are irrelevant -- the fake engine just echoes its args, and
# the arch check no-ops on a non-ELF. Error-path cases keep their bare typo'd
# name (they fail at resolution, before abs_elf).
DUMMY="$TMP/dummy.elf"; : >"$DUMMY"

# expect: assert rc + output regex (shared helper from tests/lib/log.sh)

# 2a. default = the sole cycle-accurate engine; it runs with the ELF appended
expect 0 'RAN:m1 args:.*dummy\.elf' \
  env ANDESIM_ENGINES_DIR="$D1" "$BIN" run --mode cycle "$DUMMY"
# 2b. two cycle-accurate engines, no --engine: ambiguous, names both
expect 2 'multiple cycle-accurate.*vsim:v1.*vsim:v2' \
  env ANDESIM_ENGINES_DIR="$D2" "$BIN" run --mode cycle dummy.elf
# 2c. explicit --engine picks the named binary (different <cfg> runs the other)
expect 0 'RAN:m1' \
  env ANDESIM_ENGINES_DIR="$D2" "$BIN" run --mode cycle --engine vsim:v1 "$DUMMY"
expect 0 'RAN:m2' \
  env ANDESIM_ENGINES_DIR="$D2" "$BIN" run --mode cycle --engine vsim:v2 "$DUMMY"
# 2d. no cycle-accurate engine discoverable (qemu is functional): clear error
expect 2 'no cycle-accurate engine' \
  env ANDESIM_ENGINES_DIR="$DE" "$BIN" run --mode cycle dummy.elf
# 2e. --engine names a functional engine: wrong kind for cycle
expect 2 'cycle-accurate' \
  env ANDESIM_ENGINES_DIR="$DF" "$BIN" run --mode cycle --engine vsim:f0 dummy.elf
# 2f. --engine matches nothing discovered
expect 2 "no engine 'vsim:nope'" \
  env ANDESIM_ENGINES_DIR="$D1" "$BIN" run --mode cycle --engine vsim:nope dummy.elf
# 2g. the shared standalone spine still rejects a missing ELF / extra positional
expect 2 'missing ELF' \
  env ANDESIM_ENGINES_DIR="$D1" "$BIN" run --mode cycle
expect 2 'engine args go after --' \
  env ANDESIM_ENGINES_DIR="$D1" "$BIN" run --mode cycle a.elf b.elf
# 2h. a CLI arg error is reported before (and instead of) engine discovery:
# missing ELF wins even when no engine exists, rather than "no cycle-accurate
# engine" -- so a typo never pays for a --describe subprocess per build.
expect 2 'missing ELF' \
  env ANDESIM_ENGINES_DIR="$DE" "$BIN" run --mode cycle
# 2i. the model is named `cycle`; the old `accurate` spelling is now unknown.
expect 2 "unknown model 'accurate'" \
  env ANDESIM_ENGINES_DIR="$D1" "$BIN" run --mode accurate dummy.elf
echo "[ok] fake-engine resolution + standalone exec (all branches)"

# 3. real vsim (guarded): a cycle run prints ONLY the program's own output plus
# andesim's own "[andesim] N cycles" line -- vsim's startup banner and its
# verbose [info] log (including the raw "N cycles simulated" the driver lifts
# the count from) are hidden. Pinned to ax45mpv_premium + the vplat rt_c_hello
# fixture (UART + SimControl exit): a known-good pair that DOES exit standalone
# and prints, so every assertion is deterministic (matches f9's engine choice).
# A timeout means vsim hung -> skip (defensive), not a failure.
ENG=vsim:ax45mpv_premium
SIM="${VSIM_BIN_DIR:-$ROOT/verilator/build}/sim_ax45mpv_premium"
ELF="$ROOT/tests/fixtures/rt_c_hello.elf"
if [ -x "$SIM" ] && [ -f "$ELF" ]; then
  out=$(timeout 90 "$BIN" run --mode cycle --engine "$ENG" "$ELF" 2>&1 </dev/null); rc=$?
  if [ "$rc" -eq 124 ]; then
    echo "[skip] real cycle: vsim hung (timeout); cannot assert output format"
  else
    [ "$rc" -eq 0 ] || fail "real cycle: rt_c_hello exited rc=$rc (expected 0):"$'\n'"$out"
    echo "$out" | grep -Eq '^\[andesim\] [0-9]+ cycles$' \
      || fail "real cycle: missing '[andesim] N cycles' result line:"$'\n'"$out"
    echo "$out" | grep -q 'hello' \
      || fail "real cycle: the program's own output was dropped:"$'\n'"$out"
    # vsim's banner + [info] log (incl. its raw "N cycles simulated") are hidden.
    for noise in 'cycles simulated' 'Copyright' '^\[info\]'; do
      if echo "$out" | grep -Eq "$noise"; then
        fail "real cycle: vsim noise leaked (/$noise/ should be hidden):"$'\n'"$out"
      fi
    done
    echo "[ok] real cycle: clean output -- program stdout + '[andesim] N cycles'; banner/[info]/raw count hidden (rc=0)"
  fi
else
  echo "[skip] real cycle run: need built $SIM and $ELF"
fi

ok "F8 run --mode cycle"

