// vsim resumes at _start, sets a2=3, retires slti x0, x0,  0x5A1 to trigger the
// vsim->QEMU handoff (drain state, exit 200). The infinite spin is a
// safety net if the trigger is missed.

.section .text
.globl _start
_start:
    li      a2, 3
    slti   x0, x0,  0x5A1
1:  j       1b
---
/* Tier-2 C-level handoff smoke test (2-phase: QEMU1 -> vsim).
 *
 * Phase 1 (QEMU1): printf via newlib stdio -> libgloss_vh -> semihosting,
 *   handled by QEMU. Then slti x0, x0,  0x5A0 -- plugin drains state.
 * Phase 2 (vsim):  empty body. Phase-2 rule (rt_c_helpers.h): no syscall
 *   may issue inside this span. vsim drains at slti x0, x0,  0x5A1 and exits 200.
 *
 * (The old phase-3 QEMU2 printf was removed with the QEMU2 leg.)
 */

#include "runtime/rt_c_helpers.h"
#include <stdio.h>

int main(void)
{
  printf("hello from QEMU1\n");
  fflush(stdout);

  enter_vsim();
  /* Phase 2: vsim. No syscalls. */
  exit_vsim();

  return 0;
}

    bnez    x29, check_x29
    ld      x28, 8(x5)
    li      x6, 0xA000000000000000
    addi    x6, x6, 28
    beq     x28, x6, check_x29
    addi    x29, x0, 28

check_x29:
    // Verify spilled x29 (expected = 0xA000_..._29).
    // Note: x29 is the result reg; if non-zero, skip but keep prior fail.
    bnez    x29, exit_build
    ld      x28, 16(x5)
    li      x6, 0xA000000000000000
    addi    x6, x6, 29
    beq     x28, x6, exit_build
    addi    x29, x0, 29

exit_build:
    mv      a2, x29
    SEMIHOST_EXIT a2
// Shared exit-via-semihosting macro for hybrid round-trip fixtures.
//
// SEMIHOST_EXIT exit_reg
//   Builds the {reason=ADP_Stopped_ApplicationExit, exit_code=<exit_reg>}
//   16-byte block at 0x00001000, sets a0=SYS_EXIT_EXTENDED (0x20), a1=block,
//   then issues the RISC-V semihosting `slli x0,x0,0x1f; ebreak; srai x0,x0,0x7`
//   triple. exit_reg may be any GPR holding the desired host exit code; this
//   macro clobbers t0, t1, a0, a1.
//
// QEMU's host-exit returns the low 8 bits of <exit_reg> as the process status.

.macro SEMIHOST_EXIT exit_reg
    li      t0, 0x00001000
    li      t1, 0x20026                     // ADP_Stopped_ApplicationExit
    sd      t1, 0(t0)
    sd      \exit_reg, 8(t0)
    li      a0, 0x20                        // SYS_EXIT_EXTENDED
    mv      a1, t0
    .option push
    .option norvc
    slli    x0, x0, 0x1f
    ebreak
    srai    x0, x0, 0x7
    .option pop
99: j       99b
.endm

